components.css:
.ds-btn-cta { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; font-weight: 600; line-height: 1; gap: 6px; height: 40px; padding: 0 16px; font-size: 14px; background: #1f2937; color: #f9fafb; border: 1px solid #1f2937; transition: background-color .2s cubic-bezier(.4,0,.2,1), border-color .2s; }
.ds-btn-cta:hover { background: #111827; border-color: #111827; }
.ds-btn-cta:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }
.ds-btn-cta:disabled { opacity: .2; pointer-events: none; }

.ds-btn-row { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; font-weight: 600; line-height: 1; gap: 6px; height: 32px; padding: 0 12px; font-size: 12px; background: transparent; color: #1a1d23; border: 1px solid transparent; transition: background-color .15s cubic-bezier(.4,0,.2,1); }
.ds-btn-row:hover { background: #f9fafb; }
.ds-btn-row.ds-active { background: #e5e7eb; }
.ds-btn-row:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-btn-stop { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; font-weight: 600; line-height: 1; gap: 6px; height: 32px; padding: 0 12px; font-size: 12px; background: transparent; color: #dc2626; border: 1px solid #e5e7eb; transition: background-color .15s, border-color .15s; }
@media (hover: hover) { .ds-btn-stop:hover { background: color-mix(in oklab, #dc2626 8%, transparent); border-color: color-mix(in oklab, #dc2626 40%, #e5e7eb); } }
.ds-btn-stop:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-btn-danger { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; font-weight: 600; line-height: 1; gap: 6px; height: 32px; padding: 0 12px; font-size: 12px; background: #dc2626; color: #ffffff; border: 1px solid #dc2626; transition: background-color .15s cubic-bezier(.4,0,.2,1); }
.ds-btn-danger:hover { background: #b91c1c; border-color: #b91c1c; }
.ds-btn-danger:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-btn-quiet-danger { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; font-weight: 600; line-height: 1; gap: 6px; height: 32px; padding: 0 12px; font-size: 12px; background: transparent; color: #dc2626; border: 1px solid transparent; transition: background-color .15s; }
.ds-btn-quiet-danger:hover { background: #f9fafb; }
.ds-btn-quiet-danger:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-btn-chip { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; font-weight: 600; line-height: 1; gap: 4px; height: 24px; padding: 0 8px; font-size: 12px; background: transparent; color: #1a1d23; border: 1px solid transparent; transition: background-color .15s cubic-bezier(.4,0,.2,1); }
.ds-btn-chip:hover { background: #f9fafb; }
.ds-btn-chip.ds-active { background: #e5e7eb; }
.ds-btn-chip:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-btn-quick { display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; cursor: pointer; font-family: 'Inter', system-ui, sans-serif; line-height: 1; gap: 6px; height: 32px; padding: 0 12px; font-size: 12px; font-weight: 500; background: transparent; color: #1a1d23; border: 1px solid #e5e7eb; transition: background-color .15s; }
.ds-btn-quick:hover { background: #f9fafb; }
.ds-btn-quick:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-input { height: 40px; padding: 0 12px; width: 100%; max-width: 20rem; background: #ffffff; color: #1a1d23; border: 1px solid rgba(26,29,35,.2); border-radius: 10px; font: 400 14px/1 'Inter', system-ui, sans-serif; caret-color: #1a1d23; }
.ds-input::placeholder { color: rgba(26,29,35,.5); }
.ds-input:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; border-color: #1a1d23; }
.ds-input[aria-invalid=true] { border-color: #dc2626; }
.ds-input:disabled { background: #f9fafb; color: rgba(26,29,35,.4); cursor: not-allowed; }

.ds-card { background: #ffffff; color: #1a1d23; border: 1px solid #e5e7eb; border-radius: 10px; padding: 24px; }
.ds-card-title { margin: 0 0 12px; font: 600 19.2px/1.3 'Inter', system-ui, sans-serif; letter-spacing: -0.01em; }
.ds-card-body { margin: 0; font: 400 16px/1.55 'Inter', system-ui, sans-serif; color: rgba(26,29,35,.72); }
.ds-card-total { display: flex; gap: 24px; align-items: baseline; margin-top: 20px; padding-top: 14px; border-top: 2px solid #e5e7eb; font: 400 14px/1.55 'Inter', system-ui, sans-serif; }
.ds-num { font-family: 'JetBrains Mono', ui-monospace, monospace; font-variant-numeric: tabular-nums; font-weight: 600; }

.ds-pill, .ds-tag, .ds-doc { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 999px; font: 550 13.3px/1.2 'Inter', system-ui, sans-serif; color: #1a1d23; }
.ds-pill-active { background: color-mix(in srgb, #10b981 15%, transparent); color: #047857; }
.ds-pill-paused { background: color-mix(in srgb, #f59e0b 15%, transparent); color: #b45309; }
.ds-tag { background: #f9fafb; font-weight: 400; }
.ds-doc { font-size: 12px; font-weight: 500; border: 1px solid #e5e7eb; }
.ds-doc-sent { color: #4f46e5; border-color: color-mix(in oklab, #4f46e5 40%, #e5e7eb); }
.ds-doc-paid { color: #047857; background: color-mix(in oklab, #10b981 12%, transparent); border-color: transparent; }

.ds-nav { display: flex; align-items: center; gap: 4px; flex-wrap: nowrap; height: 48px; padding: 0 16px; background: #ffffff; border-bottom: 1px solid #e5e7eb; }
.ds-wordmark { font: 620 21.6px/1 'Fraunces', 'Iowan Old Style', Georgia, serif; font-variation-settings: 'SOFT' 40, 'WONK' 1, 'opsz' 48; letter-spacing: -0.03em; flex-shrink: 0; margin-right: 8px; }
.ds-ws { min-width: 0; flex: 0 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 500 13.3px/1 'Inter', system-ui, sans-serif; margin-right: 8px; }
.ds-nav-link { display: inline-flex; align-items: center; flex-shrink: 0; gap: 6px; height: 32px; padding: 0 12px; border-radius: 10px; font: 600 12px/1 'Inter', system-ui, sans-serif; color: #1a1d23; text-decoration: none; white-space: nowrap; transition: background-color .15s; }
.ds-nav-link:hover { background: #f9fafb; }
.ds-nav-link.ds-active { background: #e5e7eb; }
.ds-nav-link:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-tabbar { display: grid; grid-template-columns: repeat(3, 1fr); background: #ffffff; border-top: 1px solid #e5e7eb; }
.ds-tab { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; min-height: 3.5rem; font: 500 12px/1.2 'Inter', system-ui, sans-serif; color: color-mix(in srgb, #1a1d23 60%, transparent); text-decoration: none; }
.ds-tab.ds-active { color: #6366f1; }
.ds-tab:active { transform: scale(0.96); }
.ds-tab:focus-visible { outline: 2px solid #6366f1; outline-offset: -2px; }

.ds-table { width: 100%; border-collapse: collapse; font: 400 14px/1.55 'Inter', system-ui, sans-serif; color: #1a1d23; }
.ds-table th { text-align: left; padding: 12px 16px; border-bottom: 1px solid #e5e7eb; font-weight: 600; }
.ds-table td { padding: 12px 16px; border-bottom: 1px solid #e5e7eb; }
.ds-table tbody tr:nth-child(even) { background: #f9fafb; }
.ds-table tfoot td { border-top: 2px solid #e5e7eb; border-bottom: 0; font-weight: 600; }
.ds-num { font-family: 'JetBrains Mono', ui-monospace, monospace; font-variant-numeric: tabular-nums; font-size: .92em; }
